// ==========================================================================
// 编制表单编码注册表 (Budget Form Registry)
// --------------------------------------------------------------------------
// 全系统所有编制表单的统一编码源。编码与左侧导航树 (LeftTreeSidebar) 保持一致：
//   A*  系统设置与基础数据   BA 编制前提与假设   BB 业务预算编制
//   BF  资金与财务预算       BO 编制汇总与检查
// 预算凭证 (BudgetLedgerEntry.sourceFormCode) 通过本表回溯"分录由哪个表单生成"。
// ==========================================================================

export interface BudgetFormDef {
  code: string;      // 表单编码 (如 BB.1.2)
  name: string;      // 表单名称
  tab: string;       // 对应 NavTabType
  subTab?: string;   // 子页签 (主数据/标准成本等)
  group: 'A' | 'BA' | 'BB' | 'BF' | 'BO';
  generatesVoucher?: boolean; // 是否为预算凭证 (分录) 的来源表单
}

export interface BudgetFieldDef {
  formCode: string;
  fieldCode: string;
  fieldName: string;
  dataType: 'string' | 'number' | 'date' | 'select' | 'text';
  inputMode: '手工' | '选择' | '公式' | '系统带出' | '自动';
  required: boolean;
  source?: string;
  remark?: string;
  /**
   * 是否下拉（可选，显式声明后优先于推导规则）。
   * 缺省推导＝「录入方式=选择」或「数据类型=select」；系统带出/派生的列即使值域来自字典
   * （dataType 登记为 select）也应显式声明 false，避免「是否下拉=是」与「系统带出、不可手工选」自相矛盾。
   */
  dropdown?: boolean;
}

const field = (formCode: string, fieldCode: string, fieldName: string, dataType: BudgetFieldDef['dataType'], inputMode: BudgetFieldDef['inputMode'], required = false, source?: string, remark?: string, dropdown?: boolean): BudgetFieldDef => ({ formCode, fieldCode, fieldName, dataType, inputMode, required, source, remark, dropdown });

