// 分录引擎使用的来源表单编码常量 (避免魔法字符串)
export const FORM_CODES = {
  HARD_SOFT_REVENUE: 'BB.1.3',
  EQUITY_INVESTMENT: 'BF.1',
  TAX_BUDGET: 'BF.4',
  SUBJECT_ADJUSTMENT: '',
} as const;

const FORM_BY_CODE = new Map(BUDGET_FORM_REGISTRY.map(f => [f.code, f]));

export function getFormByCode(code: string): BudgetFormDef | undefined {
  return FORM_BY_CODE.get(code);
}

export function getFormName(code: string): string {
  return FORM_BY_CODE.get(code)?.name ?? code;
}

// 表单来源展示文本: "BB.1.2 软硬件收入与成本预算"
export function formatFormSource(code: string): string {
  return `${code} ${getFormName(code)}`;
}
